import argparse, contextlib, io

def port(text):
    try:
        n = int(text)
    except ValueError:
        raise argparse.ArgumentTypeError(f"{text!r} is not a number") from None
    if not 1 <= n <= 65535:
        raise argparse.ArgumentTypeError(f"{n} is outside 1..65535")
    return n

p = argparse.ArgumentParser(prog="listen")
p.add_argument("-p", "--port", type=port, default=8080)
group = p.add_mutually_exclusive_group()
group.add_argument("--json", action="store_true")
group.add_argument("--csv", action="store_true")

for argv in (["-p", "443"], ["-p", "70000"], ["-p", "http"], ["--json", "--csv"]):
    err = io.StringIO()
    try:
        with contextlib.redirect_stderr(err):
            print(p.parse_args(argv))
    except SystemExit as e:
        print(e.code, err.getvalue().strip().splitlines()[-1])

#!/usr/bin/env python3
"""tool.py - template for a command-line tool that behaves in pipelines."""
import argparse
import logging
import sys

log = logging.getLogger("tool")


def build_parser():
    p = argparse.ArgumentParser(prog="tool", description=__doc__.splitlines()[0])
    p.add_argument("files", nargs="*", help="input files; none or '-' reads stdin")
    p.add_argument("-n", "--top", type=int, default=5, metavar="N", help="how many results (default: %(default)s)")
    p.add_argument("-v", "--verbose", action="count", default=0, help="-v for INFO, -vv for DEBUG")
    return p


def lines(paths):
    """Yield lines from files, or from stdin when no path (or '-') is given."""
    for path in paths or ["-"]:
        if path == "-":
            yield from sys.stdin
        else:
            with open(path, encoding="utf-8", errors="replace") as fh:
                yield from fh


def run(args):
    count = 0
    for line in lines(args.files):
        count += 1
        log.debug("line %d: %r", count, line.rstrip())
    print(count)
    return 0


def main(argv=None):
    args = build_parser().parse_args(argv)
    level = (logging.WARNING, logging.INFO, logging.DEBUG)[min(args.verbose, 2)]
    logging.basicConfig(level=level, format="%(levelname)s %(message)s", stream=sys.stderr)
    try:
        return run(args)
    except FileNotFoundError as err:
        print(f"tool: {err.filename}: no such file", file=sys.stderr)
        return 2
    except BrokenPipeError:
        return 0
    except KeyboardInterrupt:
        return 130


if __name__ == "__main__":
    sys.exit(main())

