from collections import Counter

def top_networks(addresses, prefix=24, n=2):
    counts = Counter()
    for text in addresses:
        try:
            net = ipaddress.ip_network(f"{text}/{prefix}", strict=False)
        except ValueError:
            continue
        counts[str(net)] += 1
    return counts.most_common(n)

