"""Pure functions: no printing, no argument parsing, easy to test."""
import ipaddress


def parse_network(text):
    """Accept 'a.b.c.d/len', 'a.b.c.d/mask' or a bare address; host bits are allowed."""
    try:
        return ipaddress.ip_interface(text)
    except ValueError:
        raise ValueError(f"not an address or network: {text!r}") from None


def usable_range(net):
    """First and last host address. IPv4 /30 and shorter lose the network and broadcast addresses."""
    if net.version == 4 and net.prefixlen < 31:
        return net[1], net[-2]
    return net[0], net[-1]


def describe(text):
    """Return an ordered dict of facts about the network that contains the address."""
    iface = parse_network(text)
    net = iface.network
    first, last = usable_range(net)
    info = {
        "address": str(iface.ip),
        "network": str(net.network_address),
        "prefix": net.prefixlen,
        "netmask": str(net.netmask),
        "wildcard": str(net.hostmask),
    }
    if net.version == 4:
        info["broadcast"] = str(net.broadcast_address)
    info["first"], info["last"] = str(first), str(last)
    info["usable"] = int(last) - int(first) + 1
    info["private"] = net.is_private
    return info


def split(text, new_prefix):
    """Cut the network into subnets with a longer prefix."""
    net = parse_network(text).network
    if new_prefix < net.prefixlen:
        raise ValueError(f"new prefix /{new_prefix} is shorter than /{net.prefixlen}")
    if new_prefix > net.max_prefixlen:
        raise ValueError(f"prefix /{new_prefix} is longer than {net.max_prefixlen} bits")
    return [str(s) for s in net.subnets(new_prefix=new_prefix)]


def contains(network_text, address_text):
    net = parse_network(network_text).network
    try:
        addr = ipaddress.ip_address(address_text)
    except ValueError:
        raise ValueError(f"not an IP address: {address_text!r}") from None
    return addr in net


def summarize(texts):
    """Collapse networks into the smallest list that covers exactly the same addresses."""
    nets = [parse_network(t).network for t in texts]
    return [str(n) for n in ipaddress.collapse_addresses(nets)]

import argparse, contextlib, io, ipaddress, json, sys

__version__ = "0.1.0"

# ---- core.py ----
def parse_network(text):
    try:
        return ipaddress.ip_interface(text)
    except ValueError:
        raise ValueError(f"not an address or network: {text!r}") from None

def usable_range(net):
    if net.version == 4 and net.prefixlen < 31:
        return net[1], net[-2]
    return net[0], net[-1]

def describe(text):
    iface = parse_network(text)
    net = iface.network
    first, last = usable_range(net)
    info = {"address": str(iface.ip), "network": str(net.network_address), "prefix": net.prefixlen,
            "netmask": str(net.netmask), "wildcard": str(net.hostmask)}
    if net.version == 4:
        info["broadcast"] = str(net.broadcast_address)
    info["first"], info["last"] = str(first), str(last)
    info["usable"] = int(last) - int(first) + 1
    info["private"] = net.is_private
    return info

def split(text, new_prefix):
    net = parse_network(text).network
    if new_prefix < net.prefixlen:
        raise ValueError(f"new prefix /{new_prefix} is shorter than /{net.prefixlen}")
    return [str(s) for s in net.subnets(new_prefix=new_prefix)]

def contains(network_text, address_text):
    net = parse_network(network_text).network
    try:
        addr = ipaddress.ip_address(address_text)
    except ValueError:
        raise ValueError(f"not an IP address: {address_text!r}") from None
    return addr in net

def summarize(texts):
    nets = [parse_network(t).network for t in texts]
    return [str(n) for n in ipaddress.collapse_addresses(nets)]

# ---- cli.py ----
def build_parser():
    parser = argparse.ArgumentParser(prog="ipcalc", description="Subnet calculator.")
    sub = parser.add_subparsers(dest="command", required=True, metavar="COMMAND")
    p_info = sub.add_parser("info")
    p_info.add_argument("target")
    p_info.add_argument("--json", action="store_true")
    p_info.set_defaults(func=cmd_info)
    p_split = sub.add_parser("split")
    p_split.add_argument("target")
    p_split.add_argument("-p", "--prefix", type=int, required=True)
    p_split.set_defaults(func=cmd_split)
    p_in = sub.add_parser("contains")
    p_in.add_argument("target")
    p_in.add_argument("address")
    p_in.set_defaults(func=cmd_contains)
    p_sum = sub.add_parser("summarize")
    p_sum.add_argument("networks", nargs="+")
    p_sum.set_defaults(func=cmd_summarize)
    return parser

def cmd_info(args):
    info = describe(args.target)
    if args.json:
        print(json.dumps(info, indent=2))
    else:
        for key, value in info.items():
            print(f"{key:<10}{value}")
    return 0

def cmd_split(args):
    print(*split(args.target, args.prefix), sep="\n")
    return 0

def cmd_contains(args):
    inside = contains(args.target, args.address)
    print("yes" if inside else "no")
    return 0 if inside else 1

def cmd_summarize(args):
    print(*summarize(args.networks), sep="\n")
    return 0

def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        return args.func(args)
    except ValueError as err:
        print(f"ipcalc: error: {err}", file=sys.stderr)
        return 2

# ---- drive it ----
def show(argv):
    err = io.StringIO()
    print("$ ipcalc", " ".join(argv))
    with contextlib.redirect_stderr(err):
        try:
            status = main(argv)
        except SystemExit as e:
            status = e.code
    if err.getvalue():
        print("stderr:", err.getvalue().strip().splitlines()[-1])
    print("status", status)

