import pytest

from ipcalc import contains, describe, split, summarize


def test_describe_slash26():
    info = describe("192.168.1.23/26")
    assert info["network"] == "192.168.1.0"
    assert info["broadcast"] == "192.168.1.63"
    assert info["usable"] == 62


@pytest.mark.parametrize("text, usable", [("10.0.0.0/31", 2), ("10.0.0.7/32", 1), ("10.0.0.0/30", 2)])
def test_small_networks(text, usable):
    assert describe(text)["usable"] == usable


def test_split():
    assert split("192.168.1.0/24", 26)[-1] == "192.168.1.192/26"


def test_split_rejects_shorter_prefix():
    with pytest.raises(ValueError, match="shorter"):
        split("192.168.1.0/24", 16)


def test_contains():
    assert contains("10.0.0.0/8", "10.200.3.4")
    assert not contains("10.0.0.0/8", "11.0.0.1")


def test_summarize_merges_neighbours():
    assert summarize(["192.168.0.0/24", "192.168.1.0/24"]) == ["192.168.0.0/23"]


def test_bad_input_names_the_text():
    with pytest.raises(ValueError, match="192.168.1.256"):
        describe("192.168.1.256/24")

